CSS_VARIABLES = '\n:root {\n  --bg-body: #101522;\n  --bg-panel: #161b2e;\n  --bg-header: #0f1420;\n  --bg-input: #0f1420;\n  --border-color: #2f354a;\n  --text-primary: #f5f6fa;\n  --text-secondary: #b5bfd9;\n  --text-muted: #7681a1;\n  --accent-primary: #70e1ff;\n  --accent-secondary: #22c55e;\n  --accent-tertiary: #f97316;\n  --accent-highlight: #2563eb;\n}\n'

BASE_STYLE = "\n/* Reset & Base */\n* { box-sizing: border-box; }\nbody {\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;\n  margin: 0 auto;\n  padding: 2rem;\n  max-width: 1200px;\n  background: var(--bg-body);\n  color: var(--text-primary);\n  line-height: 1.5;\n}\n\n/* Typography */\nh1, h2, h3, h4 { color: var(--accent-primary); margin-top: 2rem; margin-bottom: 1rem; line-height: 1.2; }\nh1 { font-size: 1.8rem; margin-top: 0; }\nh2 { font-size: 1.5rem; border-bottom: 1px solid var(--border-color); padding-bottom: 0.5rem; }\nh3 { font-size: 1.2rem; color: var(--text-secondary); }\na { color: var(--accent-primary); text-decoration: none; transition: opacity 0.2s; }\na:hover { opacity: 0.8; text-decoration: underline; }\n\n/* Navigation */\n.topnav {\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  background: rgba(15, 20, 32, 0.95);\n  border-bottom: 1px solid var(--border-color);\n  margin: -2rem -2rem 2rem -2rem;\n  padding: 0.75rem 2rem;\n  backdrop-filter: blur(8px);\n  display: flex;\n  align-items: center;\n  gap: 1.5rem;\n}\n.topnav strong { color: var(--text-primary); font-size: 1.1rem; margin-right: 0.5rem; }\n.topnav a { color: var(--text-secondary); font-size: 0.95rem; font-weight: 500; }\n.topnav a:hover, .topnav a.active { color: var(--accent-primary); }\n.topnav a.active { font-weight: 600; }\n\n.last-updated { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 2rem; }\n\n/* Tables */\ntable { border-collapse: collapse; width: 100%; margin: 1.5rem 0; font-variant-numeric: tabular-nums; }\nth, td { border: 1px solid var(--border-color); padding: 0.6rem 0.85rem; text-align: left; }\nth { background: #1f2840; font-weight: 600; color: #dfe6ff; user-select: none; }\ntr:nth-child(even) { background: var(--bg-panel); }\ntr:hover { background: #1a2035; }\n.summary-table { width: 100%; font-size: 0.9rem; }\n\n/* Layout & Containers */\n.section { margin-bottom: 3.5rem; }\n\ndetails {\n  background: #101628;\n  border: 1px solid var(--border-color);\n  border-radius: 10px;\n  padding: 0;\n  margin-bottom: 1.5rem;\n  overflow: hidden;\n}\ndetails summary {\n  cursor: pointer;\n  font-size: 1rem;\n  font-weight: 600;\n  color: var(--text-secondary);\n  padding: 1rem;\n  background: rgba(255,255,255,0.02);\n  transition: background 0.2s;\n}\ndetails summary:hover { background: rgba(255,255,255,0.05); color: var(--text-primary); }\ndetails[open] summary { border-bottom: 1px solid var(--border-color); }\ndetails > *:not(summary) { margin: 1rem; }\n\n.note {\n  font-size: 0.9rem;\n  color: var(--text-secondary);\n  background: rgba(47, 53, 74, 0.3);\n  padding: 1rem;\n  border-radius: 6px;\n  border-left: 3px solid var(--border-color);\n  margin-bottom: 1.5rem;\n}\n\n.definitions {\n  background: #1f2840;\n  padding: 1rem;\n  border-radius: 6px;\n  margin-bottom: 1rem;\n  font-size: 0.9rem;\n  line-height: 1.5;\n  border: 1px solid var(--border-color);\n}\n.definitions ul { margin: 0; padding-left: 1.25rem; }\n.definitions li { margin-bottom: 0.5rem; }\n.definitions li:last-child { margin-bottom: 0; }\n\n/* KPI Cards */\n.kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1.25rem; margin-bottom: 2rem; }\n.kpi-card {\n  background: var(--bg-panel);\n  padding: 1.5rem;\n  border-radius: 12px;\n  border: 1px solid var(--border-color);\n  box-shadow: 0 4px 6px rgba(0,0,0,0.1);\n  transition: transform 0.2s, box-shadow 0.2s;\n}\n.kpi-card:hover { transform: translateY(-2px); box-shadow: 0 6px 12px rgba(0,0,0,0.2); }\n.kpi-label-row { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 0.5rem; }\n.kpi-label { text-transform: uppercase; font-size: 0.7rem; color: var(--text-muted); letter-spacing: 0.05em; font-weight: 700; }\n.kpi-value { font-size: 1.75rem; color: var(--text-primary); font-weight: 700; line-height: 1.2; }\n.kpi-subtext { font-size: 0.85rem; color: var(--text-secondary); margin-top: 0.25rem; }\n.kpi-badge { font-size: 0.65rem; color: #9fb0d9; background: rgba(112,225,255,0.12); border: 1px solid var(--border-color); border-radius: 12px; padding: 0.1rem 0.5rem; }\n.kpi-footer { font-size: 0.75rem; color: var(--text-muted); margin-top: 0.75rem; padding-top: 0.75rem; border-top: 1px solid rgba(255,255,255,0.05); }\n\n/* Tooltips */\n.tooltip-icon {\n  position: relative;\n  border: 1px solid var(--accent-primary);\n  color: var(--accent-primary);\n  background: rgba(112,225,255,0.12);\n  border-radius: 50%;\n  width: 18px;\n  height: 18px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 0.7rem;\n  cursor: help;\n  margin-left: 0.4rem;\n  padding: 0;\n}\n.tooltip-icon::after {\n  content: attr(data-tooltip);\n  position: absolute;\n  bottom: 140%;\n  left: 50%;\n  transform: translateX(-50%);\n  width: max-content;\n  max-width: 280px;\n  background: #0f1420;\n  border: 1px solid var(--border-color);\n  border-radius: 6px;\n  padding: 0.75rem;\n  color: #dfe6ff;\n  font-size: 0.8rem;\n  line-height: 1.4;\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity 0.15s, transform 0.15s;\n  z-index: 100;\n  box-shadow: 0 10px 25px rgba(0,0,0,0.5);\n}\n.tooltip-icon:hover::after, .tooltip-icon:focus-visible::after { opacity: 1; transform: translateX(-50%) translateY(-5px); }\n\n/* Retention Charts */\n.retention-toggle { display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 1rem; background: #1f2840; padding: 0.4rem; border-radius: 8px; width: fit-content; }\n.retention-toggle label { cursor: pointer; font-size: 0.85rem; color: #dfe6ff; display: flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.8rem; border-radius: 6px; transition: background 0.2s; }\n.retention-toggle label:hover { background: rgba(255,255,255,0.08); }\n.retention-curve { background: #151b2c; border: 1px solid var(--border-color); border-radius: 12px; padding: 1.5rem; }\n.retention-curve-header { display: flex; align-items: center; gap: 0.5rem; margin-bottom: 1rem; }\n.retention-curve-header h3 { margin: 0; font-size: 1.1rem; color: var(--text-primary); border: none; }\n.curve-body { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 1.5rem; align-items: start; }\n.curve-table-wrapper { border: 1px solid var(--border-color); border-radius: 8px; overflow: hidden; }\n.curve-table { font-size: 0.8rem; margin: 0; border: none; }\n.curve-table th, .curve-table td { border: none; border-bottom: 1px solid var(--border-color); padding: 0.5rem 0.75rem; }\n.curve-table tr:last-child td { border-bottom: none; }\n\n/* Responsive */\n@media (max-width: 960px) {\n  .curve-body { grid-template-columns: 1fr; }\n  body { padding: 1rem; }\n  .topnav { margin: -1rem -1rem 1.5rem -1rem; padding: 0.75rem 1rem; overflow-x: auto; }\n}\n"

COINBASE_CALC_STYLE = '\n<style>\n.coinbase-wrapper {\n  max-width: 960px;\n  margin: 0 auto;\n  background: var(--bg-panel);\n  border: 1px solid var(--border-color);\n  border-radius: 12px;\n  padding: 2rem;\n  color: var(--text-primary);\n}\n.coinbase-wrapper h1,\n.coinbase-wrapper h2,\n.coinbase-wrapper h3 {\n  color: var(--accent-primary);\n}\n.coinbase-wrapper .subtitle {\n  color: var(--text-secondary);\n  margin-bottom: 1.5rem;\n}\n.coinbase-wrapper .baseline {\n  background: var(--bg-header);\n  border-left: 4px solid var(--accent-primary);\n  padding: 1rem;\n  margin-bottom: 1.5rem;\n}\n.coinbase-wrapper .baseline-stats {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n  gap: 1rem;\n  margin-top: 1rem;\n}\n.coinbase-wrapper .baseline-stat {\n  color: var(--text-secondary);\n  font-size: 0.9rem;\n}\n.coinbase-wrapper .baseline-stat strong {\n  font-size: 1.25rem;\n  color: var(--text-primary);\n}\n.coinbase-wrapper .presets {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.75rem;\n  margin-bottom: 1.5rem;\n}\n.coinbase-wrapper .preset-btn {\n  flex: 1;\n  min-width: 140px;\n  padding: 0.9rem 1.2rem;\n  border-radius: 8px;\n  border: 1px solid var(--border-color);\n  background: linear-gradient(135deg, #1f2840, #101522);\n  color: var(--text-primary);\n  cursor: pointer;\n  transition: border-color 0.2s, transform 0.2s;\n}\n.coinbase-wrapper .preset-btn:hover {\n  border-color: var(--accent-primary);\n  transform: translateY(-1px);\n}\n.coinbase-wrapper .preset-btn .target {\n  font-size: 1.2rem;\n  font-weight: 600;\n}\n.coinbase-wrapper .preset-btn .desc {\n  color: var(--text-secondary);\n  font-size: 0.8rem;\n}\n.coinbase-wrapper .slider-group {\n  margin-bottom: 1.75rem;\n}\n.coinbase-wrapper .slider-label {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 0.5rem;\n  font-size: 0.95rem;\n  color: var(--text-secondary);\n}\n.coinbase-wrapper .slider-value {\n  font-size: 1.35rem;\n  font-weight: 600;\n  color: var(--accent-primary);\n  border: 1px solid var(--border-color);\n  border-radius: 6px;\n  padding: 0.2rem 0.6rem;\n  background: var(--bg-input);\n}\n.coinbase-wrapper input[type="range"] {\n  width: 100%;\n  height: 6px;\n  border-radius: 3px;\n  background: var(--border-color);\n  accent-color: var(--accent-primary);\n}\n.coinbase-wrapper .results {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n  gap: 1rem;\n  margin-bottom: 1.5rem;\n}\n.coinbase-wrapper .result-card {\n  background: var(--bg-input);\n  border: 1px solid var(--border-color);\n  border-radius: 10px;\n  padding: 1rem;\n  text-align: center;\n}\n.coinbase-wrapper .result-value {\n  font-size: 2rem;\n  font-weight: 600;\n  color: var(--accent-primary);\n}\n.coinbase-wrapper .result-label {\n  color: var(--text-secondary);\n  font-size: 0.9rem;\n  margin-top: 0.4rem;\n}\n.coinbase-wrapper .efficiency {\n  color: var(--text-primary);\n  font-size: 0.95rem;\n  margin-bottom: 1rem;\n}\n.coinbase-wrapper .efficiency strong {\n  color: var(--accent-primary);\n}\n.coinbase-wrapper .notes {\n  color: var(--text-secondary);\n  font-size: 0.9rem;\n  line-height: 1.5;\n}\n.coinbase-wrapper .notes li {\n  margin-left: 1.2rem;\n  margin-bottom: 0.4rem;\n}\n@media (max-width: 600px) {\n  .coinbase-wrapper {\n    padding: 1.25rem;\n  }\n  .coinbase-wrapper .slider-label {\n    flex-direction: column;\n    align-items: flex-start;\n    gap: 0.3rem;\n  }\n}\n</style>\n'

PLOTLY_EMBED_STYLE = '\n<style>\n.plotly-embed {\n  background: var(--bg-panel);\n  border: 1px solid var(--border-color);\n  border-radius: 12px;\n  padding: 1.5rem;\n  overflow: auto;\n}\n</style>\n'

INDEX_STYLE = "\n/* Sidebar layout specific to the index page */\nbody { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; background: var(--bg-body); color: var(--text-primary); margin: 0; min-height: 100vh; display: flex; }\n.sidebar { width: 260px; background: var(--bg-header); border-right: 1px solid var(--border-color); padding: 1.5rem; position: sticky; top: 0; height: 100vh; box-sizing: border-box; display: flex; flex-direction: column; }\n.sidebar h2 { color: var(--accent-primary); margin-top: 0; margin-bottom: 1.5rem; font-size: 1.2rem; padding-bottom: 0.75rem; border-bottom: 1px solid var(--border-color); }\n.nav { flex: 1; display: flex; flex-direction: column; gap: 0.25rem; }\n.nav a { display: block; padding: 0.6rem 0.8rem; color: var(--text-secondary); text-decoration: none; border-radius: 6px; transition: background 0.2s, color 0.2s; font-weight: 500; }\n.nav a:hover { color: var(--text-primary); background: rgba(255,255,255,0.03); }\n.nav a.active { color: var(--accent-primary); background: rgba(112, 225, 255, 0.08); font-weight: 600; }\n.content { flex: 1; display: flex; flex-direction: column; height: 100vh; overflow: hidden; }\n.topbar { padding: 0.75rem 1.5rem; border-bottom: 1px solid var(--border-color); background: var(--bg-body); display: flex; align-items: center; justify-content: space-between; }\n.topbar p { margin: 0; color: var(--text-secondary); font-size: 0.9rem; }\niframe { flex: 1; border: none; width: 100%; background: var(--bg-body); }\nfooter { padding: 0.75rem 1.5rem; font-size: 0.8rem; color: var(--text-muted); border-top: 1px solid var(--border-color); background: var(--bg-header); }\n.open-link { display: inline-flex; align-items: center; gap: 0.4rem; font-size: 0.85rem; color: var(--accent-primary); text-decoration: none; font-weight: 500; }\n.open-link:hover { text-decoration: underline; }\n"

